module asyn_fifo (
    input wclk, 
    input rclk, 
    input wrstn, 
    input rrstn, 
    input winc, 
    input rinc, 
    input [WIDTH-1:0] wdata,
    output wfull, 
    output rempty, 
    output [WIDTH-1:0] rdata
);
// Parameter definitions
parameter WIDTH = 8;
parameter DEPTH = 16;
// Internal wires and regs
reg [WIDTH-1:0] RAM_MEM [0:DEPTH-1];
reg [($clog2(DEPTH))-1:0] waddr_bin, raddr_bin;
reg [($clog2(DEPTH))-1:0] wptr, rptr;
reg [($clog2(DEPTH))-1:0] wptr_buff, rptr_buff;
reg [($clog2(DEPTH))-1:0] wptr_syn, rptr_syn;
wire wen, ren;
wire [($clog2(DEPTH))-1:0] waddr, raddr;
// Assignments
assign wen = winc && !wfull;
assign ren = rinc && !rempty;
assign waddr = waddr_bin[$clog2(DEPTH)-1:0];
assign raddr = raddr_bin[$clog2(DEPTH)-1:0];
assign wfull = (wptr == {~rptr_syn[$clog2(DEPTH)-1:$clog2(DEPTH)-2], rptr_syn[$clog2(DEPTH)-3:0]});
assign rempty = (rptr == wptr_syn);
// Dual-port RAM implementation
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        waddr_bin <= 0;
    end else if (winc && !wfull) begin
        waddr_bin <= waddr_bin + 1;
    end
end
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        raddr_bin <= 0;
    end else if (rinc && !rempty) begin
        raddr_bin <= raddr_bin + 1;
    end
end
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr <= 0;
    end else begin
        wptr <= wptr_buff;
    end
end
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr <= 0;
    end else begin
        rptr <= rptr_buff;
    end
end
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        wptr_buff <= 0;
    end else begin
        wptr_buff <= wptr;
    end
end
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        rptr_buff <= 0;
    end else begin
        rptr_buff <= rptr;
    end
end
always @(posedge wclk or negedge wrstn) begin
    if (!wrstn) begin
        rptr_syn <= 0;
    end else begin
        rptr_syn <= rptr_buff;
    end
end
always @(posedge rclk or negedge rrstn) begin
    if (!rrstn) begin
        wptr_syn <= 0;
    end else begin
        wptr_syn <= wptr_buff;
    end
end
always @(posedge wclk) begin
    if (wen) begin
        RAM_MEM[waddr] <= wdata;
    end
end
assign rdata = RAM_MEM[raddr];
endmodule
